import{z as d,x as p,o as n,c as i,q as o,j as s,D as r,d as t,s as l,S as A,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"Chandy–Lamport 快照","description":"","frontmatter":{"title":"Chandy–Lamport 快照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/chandy-lamport.md","filePath":"cs/chandy-lamport.md","lastUpdated":1791413859000}'),B={name:"cs/chandy-lamport.md"};function m(h,a,F,c,u,C){const e=p("Mermaid");return n(),i("div",null,[a[2]||(a[2]=o('<h1 id="chandy–lamport-快照" tabindex="-1">Chandy–Lamport 快照 <a class="header-anchor" href="#chandy–lamport-快照" aria-label="Permalink to &quot;Chandy–Lamport 快照&quot;">​</a></h1><div class="epigraph"><p>没有全局时刻，也能切一刀：标记沿 FIFO 信道走，进程记录本地状态，信道记录标记前的在途消息。切出的是一致割。</p><footer>—— 据 Chandy and Lamport, Distributed Snapshots, TOCS 1985 整理</footer></div><p>上一课<a href="/cs/hlc">HLC</a>给了可读时间戳，仍不是「所有进程同一瞬间」。缺口是<strong>全局状态</strong>：死锁检测、检查点、算账要对一个从未同时存在过的组合状态说话。本课不靠 NTP，不靠向量比较出全局时刻。后课故障检测器问的是「谁活着」，不是「系统此刻的变量」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一致全局状态：割不包含「已收未发」——若割里有收事件，对应发事件也在割里。<span class="marginnote">术语翻译：「割」就是竖着一刀把系统时间线切开，切面左边算进快照、右边不算；「一致」指切面里不允许出现「接收方说收到了、发送方却还没发出」的消息。直觉类比：多人合影可以各眨各的眼，但照片里不能有人拿着别人尚未递出的接力棒。</span>任意时刻把各机内存 dump 拼起来，可能看见收到了从未发送的消息。缺口是算法：在异步 FIFO 信道上，用<strong>标记消息</strong>构造一致割。</p><p>Chandy–Lamport：发起者记录自己的状态，向所有出信道发标记。进程第一次收到标记：记录状态，向尚未发过标记的出信道补发，并开始记录该入信道上标记之前的消息（信道状态）。每条信道的标记最多一次。有限步后得到快照。</p><p><span class="marginnote">假设信道 FIFO、可靠，进程不故障——与崩溃模型正交。Lai–Yang 等变体放松 FIFO，本课点名。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现检查点：快照状态 + 信道在途，作为回滚目标。死锁检测：在快照的等待图上找环。本课只保证一致性，不保证「最近」：快照对应某个可能曾出现的全局状态，不一定是触发瞬间。</p>',9)),(n(),s(A,null,{default:r(()=>[l(e,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20INIT%5B%22%E5%8F%91%E8%B5%B7%E8%80%85%E8%AE%B0%E7%8A%B6%E6%80%81%E5%B9%B6%E5%8F%91%E6%A0%87%E8%AE%B0%22%5D%20--%3E%20RECV%5B%22%E9%A6%96%E6%AC%A1%E6%94%B6%E6%A0%87%E8%AE%B0%3A%20%E8%AE%B0%E7%8A%B6%E6%80%81%22%5D%0A%20%20RECV%20--%3E%20FWD%5B%22%E5%90%91%E5%87%BA%E4%BF%A1%E9%81%93%E5%8F%91%E6%A0%87%E8%AE%B0%22%5D%0A%20%20RECV%20--%3E%20CHAN%5B%22%E8%AE%B0%E5%BD%95%E6%A0%87%E8%AE%B0%E5%89%8D%E7%9A%84%E5%85%A5%E6%B6%88%E6%81%AF%22%5D%0A%20%20CHAN%20--%3E%20CUT%5B%22%E4%B8%80%E8%87%B4%E5%89%B2%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[t("与向量钟：可以用向量定义一致割（每个进程选一个事件，集合向下封闭），那是判定；Chandy–Lamport 是"),E("strong",null,"构造"),t("。两者互补。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"FIFO 保证：标记之后的消息不会跑到标记前面被记进信道，从而避免「先收后发」穿割。可靠投递保证标记终到达。进程故障时算法要重做或改用因果日志——那是恢复协议，不是本课。",-1)),a[6]||(a[6]=E("p",null,"单条信道上，哪些消息算进快照由接收方按这条规则分类：",-1)),(n(),s(A,null,{default:r(()=>[l(e,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%8E%A5%E6%94%B6%E6%96%B9%E4%BB%8E%20FIFO%20%E4%BF%A1%E9%81%93%E5%8F%96%E5%87%BA%E4%B8%80%E6%9D%A1%E6%B6%88%E6%81%AF%22%5D%20--%3E%20Q%7B%22%E6%98%AF%E6%A0%87%E8%AE%B0%E5%90%97%3F%22%7D%0A%20%20Q%20--%20%22%E5%90%A6%22%20--%3E%20REC%5B%22%E6%B6%88%E6%81%AF%E5%85%88%E4%BA%8E%E6%A0%87%E8%AE%B0%3A%20%E8%AE%B0%E5%85%A5%E8%AF%A5%E4%BF%A1%E9%81%93%E7%8A%B6%E6%80%81%22%5D%0A%20%20REC%20--%3E%20M%0A%20%20Q%20--%20%22%E6%98%AF%22%20--%3E%20STOP%5B%22%E5%81%9C%E6%AD%A2%E8%AE%B0%E5%BD%95%E6%AD%A4%E4%BF%A1%E9%81%93%22%5D%0A%20%20STOP%20--%3E%20POST%5B%22%E5%85%B6%E5%90%8E%E5%88%B0%E8%BE%BE%E7%9A%84%E6%B6%88%E6%81%AF%E4%B8%8D%E5%B1%9E%E4%BA%8E%E5%BF%AB%E7%85%A7%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p>快照期间应用继续跑，这是相对「停全世界」的优点。<span class="marginnote">直觉类比：标记有点像银行的「日切」对账——营业不停，只是给流水画一条分界线，线前的交易进今天的账、线后的进明天。标记消息本身不装业务数据，它唯一的职责就是这条分界线。</span>代价是信道记录缓冲区，以及「快照不是实时」：检测到的死锁是快照里的死锁，可能已经自行解开。活性检测要反复拍。</p><p>本课不把数据库的 fuzzy checkpoint、ARIES 的脏页表写成分布式快照：那是单机恢复。也不把云厂商的 VM snapshot 当 Chandy–Lamport：那些通常靠存储层冻结，有近乎同步的假设。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不处理非 FIFO、不处理拜占庭标记。不把快照当线性一致读。<span class="marginnote">常见误区：初学者容易以为拍一致快照得先把所有机器的时钟对齐。实际上标记消息本身就代替了时钟——「标记先于一切后发消息」这条 FIFO 顺序约束，就是这台机器上的人工时间线，墙钟根本不参与。</span>后课默认：要全局谓词（死锁、终止），先拍一致割再在割上评价；墙钟对齐不是合法手段。故障检测下一课，用超时与怀疑，不用快照当心跳。</p><p>一致割让「分布式状态」有对象。没有它，监控里拼出来的 JSON 只是并发读的杂烩。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一致割：没有未发送却已接收的消息。</li><li>标记 + FIFO 构造快照；应用不必停。</li><li>快照是可能状态，不必是触发瞬间。</li><li>出处：Chandy and Lamport, TOCS 1985。</li></ul>',7))])}const T=d(B,[["render",m]]);export{f as __pageData,T as default};
